```typescript
function digits(n: number): number {
    const digits = String(n).split('').map(Number);
    const oddDigits = digits.filter(d => d % 2 !== 0);
    if (oddDigits.length === 0) {
        return 0;
    }
    return oddDigits.reduce((product, d) => product * d, 1);
}
```

