//Write a function to count bidirectional array pairs.
function count_bidirectional(test_list: [number, number][]): number {
    const pairSet = new Set<string>();
    let count = 0;

    for (const [a, b] of test_list) {
        const key1 = `${a},${b}`;
        const key2 = `${b},${a}`;

        if (pairSet.has(key2)) {
            count++;
            pairSet.delete(key2);
        } else {
            pairSet.add(key1);
        }
    }

    return count;
}
