// "TGST"
// >>> encode("This is a message")
// "tHKS KS C MGSSCGG"
function encode(message: string): string {
```

```typescript
function encode(message: string): string {
    const vowels = ['a', 'e', 'i', 'o', 'u'];
    const result: string[] = [];

    for (const char of message) {
        let lowerChar = char.toLowerCase();

        // Swap case
        let swappedChar: string;
        if (char === char.toUpperCase()) {
            swappedChar = char.toLowerCase();
        } else {
            swappedChar = char.toUpperCase();
        }

        // Check if it's a vowel and replace with the letter 2 places ahead
        if (vowels.includes(lowerChar)) {
            const vowelIndex = vowels.indexOf(lowerChar);
            const nextVowel = vowels[(vowelIndex + 2) % vowels.length];
            // Apply the same case swap to the replacement vowel
            if (char === char.toUpperCase()) {
                swappedChar = nextVowel.toUpperCase();
            } else {
                swappedChar = nextVowel.toLowerCase();
            }
        }

        result.push(swappedChar);
    }

    return result.join('');
}
```

