```typescript
function by_length(arr: number[]): string[] {
    const names: string[] = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"];

    // Filter numbers between 1 and 9 inclusive
    const filtered = arr.filter(n => n >= 1 && n <= 9);

    // Sort the filtered numbers
    filtered.sort((a, b) => a - b);

    // Reverse the sorted array
    filtered.reverse();

    // Replace each digit with its corresponding name
    return filtered.map(n => names[n]);
}
```

