function left_insertion(a: number[], x: number): number {
    let left = 0;
    let right = a.length;
    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (a[mid] < x) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}
