```typescript
function even_binomial_Coeff_Sum(n: number): number {
    // The sum of even-indexed binomial coefficients for (1+1)^n is 2^(n-1)
    // For n >= 1, sum_{k even} C(n,k) = 2^(n-1)
    // For n = 0, the only coefficient is C(0,0) = 1, and 2^(-1) = 0.5 which is wrong.
    // So for n=0, return 1. For n>=1, return 2^(n-1).
    if (n === 0) {
        return 1;
    }
    return Math.pow(2, n - 1);
}
```

