//Write a function that takes in a sorted array, its length (n), and an element and returns whether the element is the majority element in the given sorted array. (The majority element is the element that occurs more than n/2 times.)
function is_majority(arr: number[], n: number, x: number): boolean {
```

```typescript
function is_majority(arr: number[], n: number, x: number): boolean {
    // Find the first occurrence of x using binary search
    let first = -1;
    let low = 0;
    let high = n - 1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (arr[mid] === x) {
            first = mid;
            high = mid - 1;
        } else if (arr[mid] < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    if (first === -1) {
        return false;
    }

    // Find the last occurrence of x using binary search
    let last = -1;
    low = 0;
    high = n - 1;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (arr[mid] === x) {
            last = mid;
            low = mid + 1;
        } else if (arr[mid] < x) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    if (last === -1) {
        return false;
    }

    // Check if the count of x is more than n/2
    const count = last - first + 1;
    return count > n / 2;
}
```

