// and determines whether it is possible to perform an exchange of elements
// between them to make lst1 an array of only even numbers.
// There is no limit on the number of exchanged elements between lst1 and lst2.
// If it is possible to exchange elements between the lst1 and lst2 to make
// all the elements of lst1 to be even, return "YES".
// Otherwise, return "NO".
// For example:
// >>> exchange([1, 2, 3, 4], [1, 2, 3, 4])
// "YES"
// >>> exchange([1, 2, 3, 4], [1, 5, 3, 4])
// "NO"
// It is assumed that the input arrays will be non-empty.
function exchange(lst1: number[], lst2: number[]): string {
```

```typescript
function exchange(lst1: number[], lst2: number[]): string {
    // Count the number of odd elements in lst1
    const oddInLst1 = lst1.filter(x => x % 2 !== 0).length;

    // If there are no odd elements in lst1, it's already all even
    if (oddInLst1 === 0) {
        return "YES";
    }

    // Count the number of even elements in lst2 that can be exchanged
    // We need to replace each odd element in lst1 with an even element from lst2
    const evenInLst2 = lst2.filter(x => x % 2 === 0).length;

    // We need at least as many even numbers in lst2 as there are odd numbers in lst1
    if (evenInLst2 >= oddInLst1) {
        return "YES";
    }

    return "NO";
}
```

