//Write a function that returns integers x and y that satisfy ax + by = n as an array, or return undefined if no solution exists.
function find_solution(a: number, b: number, n: number): [number, number] | undefined {
    // Extended Euclidean Algorithm to find gcd(a, b) and x, y such that ax + by = gcd(a, b)
    function extended_gcd(a: number, b: number): [number, number, number] {
        if (b === 0) {
            return [a, 1, 0];
        }
        const [g, x1, y1] = extended_gcd(b, a % b);
        const x = y1;
        const y = x1 - Math.floor(a / b) * y1;
        return [g, x, y];
    }

    const [g, x0, y0] = extended_gcd(a, b);

    // Check if n is divisible by gcd(a, b)
    if (n % g !== 0) {
        return undefined;
    }

    // Scale the solution
    const scale = n / g;
    const x = x0 * scale;
    const y = y0 * scale;

    return [x, y];
}
```

