function fib4(n: number): number {
```

```typescript
function fib4(n: number): number {
    if (n === 0) return 0;
    if (n === 1) return 0;
    if (n === 2) return 2;
    if (n === 3) return 0;

    let a = 0; // fib4(0)
    let b = 0; // fib4(1)
    let c = 2; // fib4(2)
    let d = 0; // fib4(3)

    for (let i = 4; i <= n; i++) {
        const next = a + b + c + d;
        a = b;
        b = c;
        c = d;
        d = next;
    }

    return d;
}
```

