function lcs_of_three(X: string, Y: string, Z: string): number {
    const m = X.length;
    const n = Y.length;
    const o = Z.length;

    // Create a 3D DP array initialized to 0
    const dp: number[][][] = Array.from({ length: m + 1 }, () =>
        Array.from({ length: n + 1 }, () =>
            Array(o + 1).fill(0)
        )
    );

    // Fill the DP table
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= o; k++) {
                if (X[i - 1] === Y[j - 1] && Y[j - 1] === Z[k - 1]) {
                    dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1;
                } else {
                    dp[i][j][k] = Math.max(
                        dp[i - 1][j][k],
                        dp[i][j - 1][k],
                        dp[i][j][k - 1]
                    );
                }
            }
        }
    }

    return dp[m][n][o];
}
