//Given a positive integer n, return the count of the numbers of n-digit
// positive integers that start or end with 1.
function starts_one_ends(n: number): number {
    if (n === 1) {
        return 1;
    }
    // Numbers that start with 1: 1 followed by any (n-1) digits -> 10^(n-1) numbers
    // Numbers that end with 1: any (n-1) digits followed by 1 -> 9 * 10^(n-2) numbers
    // Numbers that both start and end with 1: 1 followed by any (n-2) digits followed by 1 -> 10^(n-2) numbers
    // By inclusion-exclusion: start_with_1 + end_with_1 - both_start_and_end_with_1
    const startWith1 = Math.pow(10, n - 1);
    const endWith1 = 9 * Math.pow(10, n - 2);
    const bothStartAndEndWith1 = Math.pow(10, n - 2);
    return startWith1 + endWith1 - bothStartAndEndWith1;
}
