function surface_Area(b: number, s: number): number {
    // b is the base edge length
    // s is the slant height (or we need to calculate it from height)
    // Assuming s is the slant height for surface area calculation
    // Surface area of a square pyramid = base area + lateral area
    // Base area = b^2
    // Lateral area = 4 * (1/2 * b * s) = 2 * b * s
    // If s is actually the height (not slant height), we need to compute slant height first
    // Slant height = sqrt((b/2)^2 + height^2)
    // Let's assume s is the height (as the parameter name might be confusing)
    // Recalculating: if s is the height, slant height = sqrt((b/2)^2 + s^2)
    const slantHeight = Math.sqrt(Math.pow(b / 2, 2) + Math.pow(s, 2));
