//Write a function to find nth polite number. geeksforgeeks.org/n-th-polite-number/
function is_polite(n: number): number {
    // A polite number is a positive integer that can be written as the sum of two or more consecutive positive integers.
    // The only numbers that are NOT polite are powers of 2.
    // So the nth polite number is the nth positive integer that is NOT a power of 2.

    // Count how many powers of 2 are less than or equal to a given number x.
    // The number of polite numbers <= x is x - floor(log2(x))
    // We need to find the smallest x such that x - floor(log2(x)) = n

    // Let's find the nth polite number directly.
    // The k-th power of 2 (starting from 2^0=1) is not polite.
    // So among the first m positive integers, the number of non-polite numbers is floor(log2(m)) + 1 (for 2^0, 2^1, ..., 2^k where 2^k <= m)
    // Actually, powers of 2: 1, 2, 4, 8, 16, ...
    // The count of powers of 2 <= m is floor(log2(m)) + 1 if we include 2^0=1.

    // The nth polite number is n + floor(log2(n)) + 1 approximately, but let's be more precise.

    // Let's think: the m-th polite number is m + k where k is the number of powers of 2 less than or equal to m + k.
    // We can binary search or use the formula.

    // The number of polite numbers up to x is x - (number of powers of 2 <= x)
    // Number of powers of 2 <= x is floor(log2(x)) + 1 (including 2^0 = 1)

    // We want x such that x - (floor(log2(x)) + 1) = n
    // So x = n + floor(log2(x)) + 1

    // Let's iterate to find x. Start with x = n + 1 and adjust.

    let x = n;
    while (true) {
        const log2x = Math.floor(Math.log2(x));
        const countPowersOf2 = log2x + 1; // powers: 2^0, 2^1, ..., 2^log2x
        const politeCount = x - countPowersOf2;
        if (politeCount === n) {
            return x;
        } else if (politeCount < n) {
            x++;
        } else {
            x--;
        }
    }
}
