//Write a tsthon function to find the sum of the product of consecutive binomial co-efficients.
function sum_Of_product(n: number): number {
    // The sum of the product of consecutive binomial coefficients C(n,k) * C(n,k+1) for k=0 to n-1
    // is equal to C(2n, n-1)
    // We compute C(2n, n-1) = (2n)! / ((n-1)! * (n+1)!)

    function factorial(x: number): number {
        if (x <= 1) return 1;
        let result = 1;
        for (let i = 2; i <= x; i++) {
            result *= i;
        }
        return result;
    }

    const numerator = factorial(2 * n);
    const denominator = factorial(n - 1) * factorial(n + 1);
    return numerator / denominator;
}
