function select_words(s: string, n: number): string[] {
    if (s.trim() === '') {
        return [];
    }

    const vowels = new Set(['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U']);

    const isConsonant = (char: string): boolean => {
        const lower = char.toLowerCase();
        return lower >= 'a' && lower <= 'z' && !vowels.has(lower);
    };

    const countConsonants = (word: string): number => {
        let count = 0;
        for (const char of word) {
            if (isConsonant(char)) {
                count++;
            }
        }
        return count;
    };

    const words = s.split(' ');
    const result: string[] = [];

    for (const word of words) {
        if (word === '') continue;
        if (countConsonants(word) === n) {
            result.push(word);
        }
    }

    return result;
}
