//Write a tsthon function to find nth bell number.
function bell_Number(n: number): number {
    if (n < 0) {
        throw new Error("n must be a non-negative integer");
    }
    if (n === 0) {
        return 1;
    }

    // Bell numbers can be computed using the Bell triangle (Aitken's array)
    // or using the recurrence relation: B(n+1) = sum_{k=0}^{n} C(n,k) * B(k)
    // We'll use the recurrence relation with dynamic programming.

    const bell: number[] = new Array(n + 1);
    bell[0] = 1;

    for (let i = 1; i <= n; i++) {
        bell[i] = 0;
        for (let k = 0; k < i; k++) {
            bell[i] += binomialCoefficient(i - 1, k) * bell[k];
        }
    }

    return bell[n];
}

function binomialCoefficient(n: number, k: number): number {
    if (k < 0 || k > n) {
        return 0;
    }
    if (k === 0 || k === n) {
        return 1;
    }
    let result = 1;
    for (let i = 0; i < k; i++) {
        result = result * (n - i) / (i + 1);
    }
    return Math.round(result);
}
```

