function modp(n: number, p: number): number {
    if (p === 1) return 0;
    if (n === 0) return 1 % p;

    // Use BigInt to avoid precision issues with large numbers
    const bigN = BigInt(n);
    const bigP = BigInt(p);

    // Compute 2^n mod p using modular exponentiation
    let result = 1n;
    let base = 2n % bigP;
    let exp = bigN;

    while (exp > 0n) {
        if (exp % 2n === 1n) {
            result = (result * base) % bigP;
        }
        base = (base * base) % bigP;
        exp = exp / 2n;
    }

    return Number(result);
}
```

