function find_even_pair(A: number[]): number {
    // XOR of two numbers is even if and only if both numbers have the same parity
    // (both even or both odd)
    // Count even and odd numbers
    let evenCount = 0;
    let oddCount = 0;

    for (const num of A) {
        if (num % 2 === 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }

    // Number of pairs with same parity: C(evenCount, 2) + C(oddCount, 2)
    const evenPairs = (evenCount * (evenCount - 1)) / 2;
    const oddPairs = (oddCount * (oddCount - 1)) / 2;

    return evenPairs + oddPairs;
}
```

