function order_by_points(nums: number[]): number[] {
    // Helper function to calculate the sum of digits of a number
    const digitSum = (n: number): number => {
        // Use absolute value for digit sum calculation
        const absN = Math.abs(n);
        let sum = 0;
        let num = absN;
        while (num > 0) {
            sum += num % 10;
            num = Math.floor(num / 10);
        }
        return sum;
    };

    // Create an array of objects with the number, its digit sum, and original index
    const indexedNums = nums.map((num, index) => ({
        num,
        digitSum: digitSum(num),
        index
    }));

    // Sort by digit sum first, then by original index
    indexedNums.sort((a, b) => {
        if (a.digitSum !== b.digitSum) {
            return a.digitSum - b.digitSum;
        }
        return a.index - b.index;
    });

    // Return the sorted numbers
    return indexedNums.map(item => item.num);
}
