function get_max_triples(n: number): number {
    // Generate the array a where a[i] = i*i - i + 1 for i from 1 to n
    // Note: The problem uses 1-based indexing for i, so a[1] = 1*1 - 1 + 1 = 1, a[2] = 4 - 2 + 1 = 3, etc.
    const a: number[] = [];
    for (let i = 1; i <= n; i++) {
        a.push(i * i - i + 1);
    }

    // Count triples (i, j, k) with i < j < k such that a[i] + a[j] + a[k] is divisible by 3
    // We can use the fact that we only care about values modulo 3.
    // Count how many elements have remainder 0, 1, or 2 when divided by 3.
    let count0 = 0;
    let count1 = 0;
    let count2 = 0;

    for (const val of a) {
        const rem = val % 3;
        if (rem === 0) count0++;
        else if (rem === 1) count1++;
        else count2++;
    }

    // We need a[i] + a[j] + a[k] ≡ 0 (mod 3)
    // The possible combinations of remainders (r1, r2, r3) that sum to 0 mod 3:
    // (0, 0, 0): C(count0, 3)
    // (1, 1, 1): C(count1, 3)
    // (2, 2, 2): C(count2, 3)
    // (0, 1, 2): count0 * count1 * count2 (since we pick one from each group, and order doesn't matter for the triple as long as indices are ordered, but since we're just counting combinations of values from different groups, each combination of one from each group corresponds to exactly one triple with i<j<k after sorting indices... wait, no. We need to be careful.)

    // Actually, since we're choosing three distinct elements from the array, and the condition is on their values mod 3, we need to count the number of ways to choose three indices i < j < k such that the sum of their remainders is 0 mod 3.
    // The key insight: if we pick one element with remainder 0, one with remainder 1, and one with remainder 2, then any combination of three such elements (one from each group) will have a sum ≡ 0 mod 3. And since all elements are distinct (different indices), we just need to count the number of ways to pick one from each group, which is count0 * count1 * count2.
    // For (0,0,0): we need to choose 3 elements from the count0 group: C(count0, 3)
    // For (1,1,1): C(count1, 3)
    // For (2,2,2): C(count2, 3)

    function combinations(n: number, k: number): number {
        if (k > n || k < 0) return 0;
        if (k === 0 || k === n) return 1;
        if (k > n / 2) k = n - k;
        let result = 1;
        for (let i = 1; i <= k; i++) {
            result = result * (n - i + 1) / i;
        }
        return result;
    }

    const triples = combinations(count0, 3) + combinations(count1, 3) + combinations(count2, 3) + count0 * count1 * count2;

    return triples;
}
