//Write a function to find the Eulerian number a(n, m).
function eulerian_num(n: number, m: number): number {
    // Eulerian number a(n, m) counts the number of permutations of {1, ..., n}
    // with exactly m ascents.
    // Base cases:
    // a(n, m) = 0 if m < 0 or m >= n
    // a(0, 0) = 1
    // a(n, 0) = 1 for n >= 1
    // Recurrence: a(n, m) = (m + 1) * a(n - 1, m) + (n - m) * a(n - 1, m - 1)

    if (n === 0 && m === 0) return 1;
    if (m < 0 || m >= n) return 0;
    if (m === 0) return 1;

    // Use dynamic programming with a 2D array
    const dp: number[][] = [];
    for (let i = 0; i <= n; i++) {
        dp[i] = new Array(n).fill(0);
    }

    // Base case: a(0, 0) = 1
    dp[0][0] = 1;

    for (let i = 1; i <= n; i++) {
        for (let j = 0; j < i; j++) {
            // a(i, j) = (j + 1) * a(i-1, j) + (i - j) * a(i-1, j-1)
            const term1 = (j + 1) * (j < i ? dp[i - 1][j] : 0);
            const term2 = (i - j) * (j - 1 >= 0 ? dp[i - 1][j - 1] : 0);
            dp[i][j] = term1 + term2;
        }
    }

    return dp[n][m];
}
```

