```

```typescript
function heap_queue_largest(nums: number[], n: number): number[] {
    if (n <= 0) return [];
    if (nums.length === 0) return [];

    // Use a min-heap of size n to keep track of the n largest elements
    const minHeap: number[] = [];

    // Helper functions for min-heap
    function heapPush(val: number): void {
        minHeap.push(val);
        let i = minHeap.length - 1;
        while (i > 0) {
            const parent = Math.floor((i - 1) / 2);
            if (minHeap[parent] <= minHeap[i]) break;
            [minHeap[parent], minHeap[i]] = [minHeap[i], minHeap[parent]];
            i = parent;
        }
    }

    function heapPop(): number {
        const top = minHeap[0];
        const last = minHeap.pop()!;
        if (minHeap.length > 0) {
            minHeap[0] = last;
            let i = 0;
            while (true) {
                let smallest = i;
                const left = 2 * i + 1;
                const right = 2 * i + 2;
                if (left < minHeap.length && minHeap[left] < minHeap[smallest]) {
                    smallest = left;
                }
                if (right < minHeap.length && minHeap[right] < minHeap[smallest]) {
                    smallest = right;
                }
                if (smallest === i) break;
                [minHeap[i], minHeap[smallest]] = [minHeap[smallest], minHeap[i]];
                i = smallest;
            }
        }
        return top;
    }

    function heapPeek(): number {
        return minHeap[0];
    }

    // Process each number
    for (const num of nums) {
        if (minHeap.length < n) {
            heapPush(num);
        } else if (num > heapPeek()) {
            heapPop();
            heapPush(num);
        }
    }

    // Extract elements and sort in descending order
    const result: number[] = [];
    while (minHeap.length > 0) {
        result.push(heapPop());
    }
    result.sort((a, b) => b - a);

    return result;
}
```

