//Write a function to create the next bigger number by rearranging the digits of a given number.
function rearrange_bigger(n: number): any {
    const digits = n.toString().split('').map(Number);
    const len = digits.length;

    // Find the first digit from the right that is smaller than the digit after it
    let i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, no bigger number is possible
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit to the right of i that is greater than digits[i]
    let j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits to the right of i
    const rightPart = digits.slice(i + 1).reverse();
    const result = [...digits.slice(0, i + 1), ...rightPart];

    const resultNumber = parseInt(result.join(''), 10);

    // Check for overflow (if the result exceeds Number.MAX_SAFE_INTEGER or doesn't fit in a safe integer)
    if (resultNumber > Number.MAX_SAFE_INTEGER || resultNumber < Number.MIN_SAFE_INTEGER) {
        return -1;
    }

    return resultNumber;
}
