// >>> sort_array([2, 4, 3, 0, 1, 5])
// [0, 1, 2, 3, 4, 5]
// >>> sort_array([2, 4, 3, 0, 1, 5, 6])
// [6, 5, 4, 3, 2, 1, 0]
function sort_array(array: number[]): number[] {
    if (array.length === 0) {
        return [];
    }

    // Create a copy of the array to avoid mutating the original
    const sorted = [...array];

    // Determine the sum of the first and last elements of the original array
    const sum = array[0] + array[array.length - 1];

    if (sum % 2 === 0) {
        // Even sum: sort in descending order
        sorted.sort((a, b) => b - a);
    } else {
        // Odd sum: sort in ascending order
        sorted.sort((a, b) => a - b);
    }

    return sorted;
}
