function count_Pairs(arr: number[], n: number): number {
    const freq: Map<number, number> = new Map();
    for (const num of arr) {
        freq.set(num, (freq.get(num) || 0) + 1);
    }

    let totalPairs = 0;
    const values = Array.from(freq.values());

    // Total number of unordered pairs from n elements is n*(n-1)/2
    // Subtract pairs where both elements are equal
    let equalPairs = 0;
    for (const count of values) {
        if (count > 1) {
            equalPairs += (count * (count - 1)) / 2;
        }
    }

    totalPairs = (n * (n - 1)) / 2 - equalPairs;

    return totalPairs;
}
```

