function get_Inv_Count(arr: number[]): number {
    // Helper function for merge sort that counts inversions
    function mergeSort(arr: number[], temp: number[], left: number, right: number): number {
        let invCount = 0;
        if (left < right) {
            const mid = Math.floor((left + right) / 2);
            invCount += mergeSort(arr, temp, left, mid);
            invCount += mergeSort(arr, temp, mid + 1, right);
            invCount += merge(arr, temp, left, mid + 1, right);
        }
        return invCount;
    }

    function merge(arr: number[], temp: number[], left: number, mid: number, right: number): number {
        let i = left;
        let j = mid;
        let k = left;
        let invCount = 0;

        while (i <= mid - 1 && j <= right) {
            if (arr[i] <= arr[j]) {
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[j++];
                invCount += (mid - i);
            }
        }

        while (i <= mid - 1) {
            temp[k++] = arr[i++];
        }

        while (j <= right) {
            temp[k++] = arr[j++];
        }

        for (i = left; i <= right; i++) {
            arr[i] = temp[i];
        }

        return invCount;
    }

    const temp = new Array(arr.length);
    return mergeSort(arr, temp, 0, arr.length - 1);
}
