function skjkasdkd(lst: number[]): number {
    // Helper function to check if a number is prime
    function isPrime(n: number): boolean {
        if (n < 2) return false;
        if (n === 2) return true;
        if (n % 2 === 0) return false;
        for (let i = 3; i <= Math.sqrt(n); i += 2) {
            if (n % i === 0) return false;
        }
        return true;
    }

    // Helper function to compute the sum of digits of a number
    function sumOfDigits(n: number): number {
        let sum = 0;
        let num = Math.abs(n);
        while (num > 0) {
            sum += num % 10;
            num = Math.floor(num / 10);
        }
        return sum;
    }

    // Find the largest prime in the array
    let largestPrime: number | null = null;
    for (const num of lst) {
        if (isPrime(num)) {
            if (largestPrime === null || num > largestPrime) {
                largestPrime = num;
            }
        }
    }

    // If no prime found, return 0
    if (largestPrime === null) {
        return 0;
    }

    // Return the sum of digits of the largest prime
    return sumOfDigits(largestPrime);
