function largest_prime_factor(n: number): number {
    let largest = -1;

    // Divide out all factors of 2
    while (n % 2 === 0) {
        largest = 2;
        n = n / 2;
    }

    // Check odd factors from 3 upwards
    let factor = 3;
    while (factor * factor <= n) {
        while (n % factor === 0) {
            largest = factor;
            n = n / factor;
        }
        factor += 2;
    }

    // If n is still greater than 1, then it is a prime factor
    if (n > 1) {
        largest = n;
    }

    return largest;
}
