```typescript
function specialFilter(nums: number[]): number {
    function getFirstDigit(n: number): number {
        n = Math.abs(n);
        while (n >= 10) {
            n = Math.floor(n / 10);
        }
        return n;
    }

    function getLastDigit(n: number): number {
        return Math.abs(n) % 10;
    }

    function isOdd(n: number): boolean {
        return n % 2 !== 0;
    }

    return nums.filter(num => {
        if (num <= 10) return false;
        const firstDigit = getFirstDigit(num);
        const lastDigit = getLastDigit(num);
        return isOdd(firstDigit) && isOdd(lastDigit);
    }).length;
}
```

