function count_nums(arr: number[]): number {
    return arr.filter(num => {
        const str = num.toString();
        let sum = 0;
        for (let i = 0; i < str.length; i++) {
            if (str[i] === '-') {
                // For negative numbers, the first digit is negative
                // e.g., -123 has signed digits -1, 2, 3
                // So we skip '-' and treat the next digit as negative
                continue;
            }
            const digit = parseInt(str[i]);
            if (i === 0 && str[0] === '-') {
                // This shouldn't happen since we skip '-'
                sum -= digit;
            } else if (str[0] === '-' && i === 1) {
                // First digit after '-' is negative
                sum -= digit;
            } else {
                sum += digit;
            }
        }
        return sum > 0;
    }).length;
}
