// [2, 5, 7]
function factorize(n: number): number[] {
```

```typescript
function factorize(n: number): number[] {
    const factors: number[] = [];
    let current = n;

    // Handle factor of 2
    while (current % 2 === 0) {
        factors.push(2);
        current /= 2;
    }

    // Handle odd factors from 3 onwards
    let divisor = 3;
    while (divisor * divisor <= current) {
        while (current % divisor === 0) {
            factors.push(divisor);
            current /= divisor;
        }
        divisor += 2;
    }

    // If current is still greater than 1, then it's a prime factor
    if (current > 1) {
        factors.push(current);
    }

    return factors;
}
```

