function pair_xor_Sum(arr: number[], n: number): number {
    let sum = 0;
    for (let bit = 0; bit < 32; bit++) {
        let countSet = 0;
        for (let i = 0; i < n; i++) {
            if ((arr[i] >> bit) & 1) {
                countSet++;
            }
        }
        let countUnset = n - countSet;
        sum += (countSet * countUnset * (1 << bit));
    }
    return sum;
}
