function do_algebra(operator: string[], operand: number[]): number {
    // We need to evaluate the expression with proper operator precedence.
    // Operators: +, -, *, //, **
    // Precedence (highest to lowest): ** (right-associative), *, //, +, -

    // First, let's build the list of operands and operators
    // We'll use a two-pass approach: first handle ** and *, //, then + and -

    // Let's create arrays for the current operands and operators
    let ops: string[] = [...operator];
    let operands: number[] = [...operand];

    // Helper function to apply an operator
    const applyOp = (op: string, a: number, b: number): number => {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return a * b;
            case '//': return Math.floor(a / b);
            case '**': return Math.pow(a, b);
            default: throw new Error(`Unknown operator: ${op}`);
        }
    };

    // First pass: handle ** (right-associative)
    // We need to handle right-associativity for **, so we process from right to left
    let newOps: string[] = [];
    let newOperands: number[] = [];

    // Start with the first operand
    newOperands.push(operands[0]);

    for (let i = 0; i < ops.length; i++) {
        if (ops[i] === '**') {
            // Right-associative: we need to handle this carefully
            // For right-associativity, we can process from right to left
            // Let's collect all ** operations and their operands
        }
        newOps.push(ops[i]);
        newOperands.push(operands[i + 1]);
    }

    // Actually, let's use a more standard approach with precedence levels
    // Precedence: ** (3, right-assoc), * (2), // (2), + (1), - (1)

    // Let's use the shunting-yard algorithm or a simpler two-pass approach

    // Two-pass approach:
    // Pass 1: Handle ** (right-associative), then *, //
    // Pass 2: Handle +, -

    // Let's redo this more carefully

    // Reset
    ops = [...operator];
    operands = [...operand];

    // Pass 1: Handle ** (right-associative)
    // For right-associative **, we process from right to left
    let i = ops.length - 1;
    while (i >= 0) {
        if (ops[i] === '**') {
            operands[i] = applyOp('**', operands[i], operands[i + 1]);
            ops.splice(i, 1);
            operands.splice(i + 1, 1);
        }
        i--;
    }

    // Pass 2: Handle * and // (left-associative)
    i = 0;
    while (i < ops.length) {
        if (ops[i] === '*' || ops[i] === '//') {
            operands[i] = applyOp(ops[i], operands[i], operands[i + 1]);
            ops.splice(i, 1);
            operands.splice(i + 1, 1);
        } else {
            i++;
        }
    }

    // Pass 3: Handle + and - (left-associative)
    i = 0;
    while (i < ops.length) {
        operands[i] = applyOp(ops[i], operands[i], operands[i + 1]);
        ops.splice(i, 1);
        operands.splice(i + 1, 1);
    }

    return operands[0];
}
