```typescript
function find_First_Missing(array: number[]): number {
    let left = 0;
    let right = array.length - 1;

    // If the first element is not 0, then 0 is the missing number
    if (array[0] !== 0) {
        return 0;
    }

    // If the last element is equal to its index, then the missing number is array.length
    if (array[right] === right) {
        return right + 1;
    }

    // Binary search to find the smallest index where array[i] !== i
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);

        if (array[mid] === mid) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return left;
}
```

