function k_smallest_pairs(nums1: number[], nums2: number[], k: number): number[][] {
    const result: number[][] = [];
    if (nums1.length === 0 || nums2.length === 0 || k <= 0) {
        return result;
    }

    // Use a min-heap approach with a priority queue
    // We'll use a simple approach with a heap-like structure
    // For efficiency, we use a heap to track the next smallest pair

    // Each element in the heap: [sum, index1, index2]
    // We start with pairs (nums1[i], nums2[0]) for all i in nums1
    // Then we extract the min and add the next element from nums2 for that index1

    interface HeapItem {
        sum: number;
        index1: number;
        index2: number;
    }

    // Simple binary min-heap
    const heap: HeapItem[] = [];

    function heapPush(item: HeapItem): void {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const parent = Math.floor((i - 1) / 2);
            if (heap[parent].sum <= heap[i].sum) break;
            [heap[parent], heap[i]] = [heap[i], heap[parent]];
            i = parent;
        }
    }

    function heapPop(): HeapItem | undefined {
        if (heap.length === 0) return undefined;
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0 && last) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let smallest = i;
                const left = 2 * i + 1;
                const right = 2 * i + 2;
                if (left < heap.length && heap[left].sum < heap[smallest].sum) {
                    smallest = left;
                }
                if (right < heap.length && heap[right].sum < heap[smallest].sum) {
                    smallest = right;
                }
                if (smallest === i) break;
                [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
                i = smallest;
            }
        }
        return top;
    }

    // Initialize heap with (nums1[i], nums2[0]) for each i
    for (let i = 0; i < nums1.length; i++) {
        heapPush({ sum: nums1[i] + nums2[0], index1: i, index2: 0 });
    }

    while (result.length < k && heap.length > 0) {
        const item = heapPop();
        if (!item) break;

        result.push([nums1[item.index1], nums2[item.index2]]);

        // Add the next pair from nums2 for the same index1
        if (item.index2 + 1 < nums2.length) {
            heapPush({
                sum: nums1[item.index1] + nums2[item.index2 + 1],
                index1: item.index1,
                index2: item.index2 + 1
            });
        }
    }

    return result;
}
