function toggle_middle_bits(n: number): number {
    if (n <= 0) return n;

    // Find the number of bits in n
    let numBits = 0;
    let temp = n;
    while (temp > 0) {
        numBits++;
        temp >>= 1;
    }

    // If there are 2 or fewer bits, no middle bits to toggle
    if (numBits <= 2) return n;

    // Create a mask with all 1s except the first and last bit
    // All 1s mask: (1 << numBits) - 1
    // Then subtract 1 to remove the last bit, and subtract (1 << (numBits - 1)) to remove the first bit
