    // to the end. So after k left rotations, the character originally at position k
    // becomes the first character, and the character at position (k-1) mod L becomes
    // the last character... 

    // Let me think more carefully. For a string s of length L:
    // - Original: s[0]s[1]...s[L-1]
    // - After 1 left rotation: s[1]s[2]...s[L-1]s[0]
    // - After 2 left rotations: s[2]s[3]...s[L-1]s[0]s[1]
    // - After k left rotations: s[k]s[k+1]...s[L-1]s[0]...s[k-1]
    // The last character after k rotations is s[(k-1) mod L] if we consider 0-indexed.
    // Wait, after k rotations, the last character is s[(k-1) % L]... let me verify:
    // k=0: last char is s[L-1]. (0-1) % L = -1 % L = L-1. Correct.
    // k=1: last char is s[0]. (1-1) % L = 0. Correct.
    // k=2: last char is s[1]. (2-1) % L = 1. Correct.

    // So after k rotations, the last bit is s[(k-1) % L].
    // The number is odd if s[(k-1) % L] == '1'.

    // We need to count for k = 0, 1, ..., n-1 (n rotations) how many have odd values.

    const L = s.length;
    if (L === 0) return 0;

    let count = 0;
    for (let k = 0; k < n; k++) {
        const lastBitIndex = (k - 1) % L;
        const adjustedIndex = lastBitIndex < 0 ? lastBitIndex + L : lastBitIndex;
        if (s[adjustedIndex] === '1') {
            count++;
        }
    }

    return count;
}
