```typescript
function right_angle_triangle(a: number, b: number, c: number): boolean {
    // Sort the sides so that the largest is last
    const sides = [a, b, c].sort((x, y) => x - y);
    const [x, y, z] = sides;

    // Check triangle inequality first (though for right triangle check, we mainly need Pythagorean theorem)
    // A valid triangle must have positive sides and satisfy triangle inequality
    if (x <= 0 || y <= 0 || z <= 0) return false;
    if (x + y <= z) return false;

    // Check Pythagorean theorem: x^2 + y^2 = z^2
    // Use a small epsilon for floating point comparison
    const epsilon = 1e-9;
    return Math.abs(x * x + y * y - z * z) < epsilon;
}
