//Find the shortest palindrome that begins with a supplied string.
// Algorithm idea is simple:
// - Find the longest postfix of supplied string that is a palindrome.
// - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
// >>> make_palindrome("")
// ""
// >>> make_palindrome("cat")
// "catac"
// >>> make_palindrome("cata")
// "catac"
function make_palindrome(string: string): string {
```

```typescript
function make_palindrome(string: string): string {
    if (string.length === 0) return "";

    // Find the longest palindromic suffix
    let longestPalindromicSuffixIndex = 0;
    for (let i = 0; i < string.length; i++) {
        // Check if substring from i to end is a palindrome
        let start = i;
        let end = string.length - 1;
        let isPalindrome = true;
        while (start < end) {
            if (string[start] !== string[end]) {
                isPalindrome = false;
                break;
            }
            start++;
            end--;
        }
        if (isPalindrome) {
            longestPalindromicSuffixIndex = i;
            break; // Found the longest (earliest starting) palindromic suffix
        }
    }

    // The prefix before the palindromic suffix
    const prefix = string.substring(0, longestPalindromicSuffixIndex);
    // Reverse the prefix
    const reversedPrefix = prefix.split('').reverse().join('');

    return string + reversedPrefix;
}
```

