function sort_array(arr: number[]): number[] {
    return [...arr].sort((a, b) => {
        const countOnesA = countOnes(a);
        const countOnesB = countOnes(b);
        if (countOnesA !== countOnesB) {
            return countOnesA - countOnesB;
        }
        return a - b;
    });
