function countOnes(n: number): number {
    // For negative numbers, we need to handle them properly.
    // In JavaScript, negative numbers are represented in two's complement.
    // We can use n >>> 0 to convert to unsigned 32-bit integer, then count bits.
    // But the problem says non-negative integers in the description, yet the example has negatives.
    // Let's handle both cases. For negative numbers, we count the number of 1 bits in their 32-bit representation.
    if (n >= 0) {
        let count = 0;
        let num = n;
        while (num > 0) {
            count += num & 1;
            num >>>= 1;
        }
        return count;
    } else {
        // For negative numbers, convert to unsigned 32-bit integer
        let num = n >>> 0;
        let count = 0;
        while (num > 0) {
            count += num & 1;
            num >>>= 1;
        }
        return count;
    }
}
