function max_product(arr: number[]): number {
    if (arr.length === 0) return 0;

    const n = arr.length;
    // dp[i] stores the maximum product of an increasing subsequence ending at index i
    const dp: number[] = new Array(n).fill(1);

    let maxProd = arr[0];

    for (let i = 0; i < n; i++) {
        dp[i] = arr[i]; // At minimum, the subsequence is just the element itself
        for (let j = 0; j < i; j++) {
            if (arr[j] < arr[i]) {
                // We can extend the increasing subsequence ending at j
                const candidate = dp[j] * arr[i];
                if (candidate > dp[i]) {
                    dp[i] = candidate;
                }
            }
        }
        if (dp[i] > maxProd) {
            maxProd = dp[i];
        }
    }

    return maxProd;
}
