//Write a function to sort an array of elements.
function pancake_sort(nums: number[]): number[] {
    const arr = [...nums];
    const n = arr.length;

    for (let size = n; size > 1; size--) {
        // Find the index of the maximum element in arr[0..size-1]
        let maxIndex = 0;
        for (let i = 1; i < size; i++) {
            if (arr[i] > arr[maxIndex]) {
                maxIndex = i;
            }
        }

        // If the maximum element is not already at the end
        if (maxIndex !== size - 1) {
            // Flip the array from 0 to maxIndex to bring the max element to the front
            reverse(arr, 0, maxIndex);
            // Flip the array from 0 to size-1 to move the max element to its correct position
            reverse(arr, 0, size - 1);
        }
    }

    return arr;
}

function reverse(arr: number[], start: number, end: number): void {
    while (start < end) {
        const temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}
