function min_Swaps(str1: string, str2: string): number {
    if (str1.length !== str2.length) {
        return -1;
    }

    let ones1 = 0;
    let ones2 = 0;

    for (const char of str1) {
        if (char === '1') ones1++;
    }

    for (const char of str2) {
        if (char === '1') ones2++;
    }

    // If the number of 1s differs, conversion is impossible
    if (ones1 !== ones2) {
        return -1;
    }

    // Count mismatches where str1 has '1' and str2 has '0'
    // and where str1 has '0' and str2 has '1'
    let mismatch1 = 0; // positions where str1[i] = '1' and str2[i] = '0'
    let mismatch0 = 0; // positions where str1[i] = '0' and str2[i] = '1'

    for (let i = 0; i < str1.length; i++) {
        if (str1[i] === '1' && str2[i] === '0') {
            mismatch1++;
        } else if (str1[i] === '0' && str2[i] === '1') {
            mismatch0++;
        }
    }

    // Each swap can fix one mismatch of each type
    // So the number of swaps needed is max(mismatch1, mismatch0)
    // But since ones1 === ones2, mismatch1 should equal mismatch0
    return mismatch1;
}
