function last(arr: number[], x: number): number {
    let left = 0;
    let right = arr.length - 1;
    let result = -1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (arr[mid] === x) {
            result = mid;
            left = mid + 1; // Continue searching in the right half for the last occurrence
