//Write a function to find the median of two sorted arrays of same size.
function get_median(arr1: number[], arr2: number[], n: number): number {
    if (n === 0) {
        throw new Error("Array size must be greater than 0");
    }

    let i = 0; // Pointer for arr1
    let j = 0; // Pointer for arr2
    let m1 = -1;
    let m2 = -1;

    // Find median by merging conceptually up to the middle
    for (let count = 0; count <= n; count++) {
        if (i === n) {
            m1 = m2;
            m2 = arr2[0];
            break;
        } else if (j === n) {
            m1 = m2;
            m2 = arr1[0];
            break;
        }

        if (arr1[i] < arr2[j]) {
            m1 = m2;
            m2 = arr1[i];
            i++;
        } else {
            m1 = m2;
            m2 = arr2[j];
            j++;
        }
    }

    return (m1 + m2) / 2;
}
