    // We can optimize space by using a 1D DP approach
    // Let dp[j] = number of sequences of current length ending with value j

    // Initialize for length 1
    const dp: number[] = new Array(m + 1).fill(0);
    for (let j = 1; j <= m; j++) {
        dp[j] = 1;
    }

    // For each subsequent length from 2 to n
    for (let i = 2; i <= n; i++) {
        const newDp: number[] = new Array(m + 1).fill(0);
        // For each possible ending value j, sum up all dp[k] where 2*k <= j, i.e., k <= j/2
        // To optimize, we can use prefix sums
        // newDp[j] = sum of dp[k] for k from 1 to floor(j/2)

        // Compute prefix sums of dp
        const prefixSum: number[] = new Array(m + 1).fill(0);
        for (let k = 1; k <= m; k++) {
            prefixSum[k] = prefixSum[k - 1] + dp[k];
        }

        for (let j = 1; j <= m; j++) {
            const maxK = Math.floor(j / 2);
            if (maxK >= 1) {
                newDp[j] = prefixSum[maxK];
            }
        }

        // Update dp
        for (let j = 1; j <= m; j++) {
            dp[j] = newDp[j];
        }
    }

    // Sum up all dp[j] for j from 1 to m
    let total = 0;
    for (let j = 1; j <= m; j++) {
        total += dp[j];
    }

    return total;
}
