        return -1; // Invalid input
    }
    if (n === 0 || n === 1) {
        return 1;
    }
    // For n >= 5, the factorial always ends in 0 because it includes factors 2 and 5
    if (n >= 5) {
        return 0;
    }
    // For n < 5, compute factorial directly
