function count_no_of_ways(n: number, k: number): number {
    if (n === 0) return 0;
    if (n === 1) return k;
    if (n === 2) return k * k;

    // For n >= 3:
    // Let same[i] = number of ways to paint i posts such that the last two posts have the same color
    // Let diff[i] = number of ways to paint i posts such that the last two posts have different colors
    //
    // Base case for i=2:
    // same[2] = k (both posts same color, k choices)
    // diff[2] = k * (k - 1) (first post k choices, second post k-1 choices different from first)
    //
    // Recurrence:
    // same[i] = diff[i-1] * 1 (to make last two same, previous two must be different, and we pick the same color as the (i-1)th post)
    // diff[i] = (same[i-1] + diff[i-1]) * (k - 1) (to make last two different, any valid coloring of i-1 posts, and we pick a color different from the (i-1)th post)

    let same = k; // same[2]
    let diff = k * (k - 1); // diff[2]

    for (let i = 3; i <= n; i++) {
        const newSame = diff;
        const newDiff = (same + diff) * (k - 1);
        same = newSame;
        diff = newDiff;
    }

    return same + diff;
}
