function choose_num(x: number, y: number): number {
    if (x > y) {
        return -1;
    }

    // Start from y and go down to find the largest even number
    let current = y;
    while (current >= x) {
        if (current % 2 === 0) {
            return current;
        }
        current--;
    }

    return -1;
}
