function histogram(test: string): {[key: string]: number} {
    const result: {[key: string]: number} = {};

    if (test.trim() === "") {
        return result;
    }

    const letters = test.split(" ");

    // Count occurrences of each letter
    const counts: {[key: string]: number} = {};
    for (const letter of letters) {
        if (letter === "") continue;
        counts[letter] = (counts[letter] || 0) + 1;
    }

    // Find the maximum count
    let maxCount = 0;
    for (const letter in counts) {
        if (counts[letter] > maxCount) {
            maxCount = counts[letter];
        }
    }

    // If no letters were found, return empty object
    if (maxCount === 0) {
        return result;
    }

    // Collect all letters with the maximum count
    for (const letter in counts) {
        if (counts[letter] === maxCount) {
            result[letter] = counts[letter];
        }
    }

    return result;
}
