```typescript
//Given a square matrix of size N*N given as an array of arrays, where each cell is associated with a specific cost. A path is defined as a specific sequence of cells that starts from the top-left cell move only right or down and ends on bottom right cell. We want to find a path with the maximum average over all existing paths. Average is computed as total cost divided by the number of cells visited in the path.
function maxAverageOfPath(cost: number[][]): number {
    const n = cost.length;
    if (n === 0) return 0;

    // Each path from top-left to bottom-right in an N*N matrix has exactly (2*N - 1) cells
    // because we make (N-1) moves right and (N-1) moves down, plus the starting cell.
    const pathLength = 2 * n - 1;

    // We need to find the path with maximum total cost, since the denominator (pathLength) is constant for all paths.
    // Use dynamic programming to find the maximum sum path.
    // dp[i][j] = maximum cost to reach cell (i, j) from (0, 0)
    const dp: number[][] = Array.from({ length: n }, () => Array(n).fill(-Infinity));

    dp[0][0] = cost[0][0];

    // Fill first row
    for (let j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost[0][j];
    }

    // Fill first column
    for (let i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost[i][0];
    }

    // Fill the rest
    for (let i = 1; i < n; i++) {
        for (let j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
        }
    }

    const maxTotalCost = dp[n - 1][n - 1];
    return maxTotalCost / pathLength;
}
```

