//Write a function to check whether it follows the sequence given in the patterns array.
function is_samepatterns(colors: string[], patterns: string[]): boolean {
    if (colors.length !== patterns.length) {
        return false;
    }

    const colorToPattern = new Map<string, string>();
    const patternToColor = new Map<string, string>();

    for (let i = 0; i < colors.length; i++) {
        const color = colors[i];
        const pattern = patterns[i];

        if (colorToPattern.has(color)) {
            if (colorToPattern.get(color) !== pattern) {
                return false;
            }
        } else {
            colorToPattern.set(color, pattern);
        }

        if (patternToColor.has(pattern)) {
            if (patternToColor.get(pattern) !== color) {
                return false;
            }
        } else {
            patternToColor.set(pattern, color);
        }
    }

    return true;
}
```

