function max_sum(arr: number[]): number {
```

```typescript
function max_sum(arr: number[]): number {
    const n = arr.length;
    if (n === 0) return 0;
    if (n === 1) return arr[0];

    // msis[i] = maximum sum of an increasing subsequence ending at index i
    const msis: number[] = new Array(n).fill(0);
    // msds[i] = maximum sum of a decreasing subsequence starting at index i
    const msds: number[] = new Array(n).fill(0);

    // Compute msis: maximum sum increasing subsequence ending at each index
    for (let i = 0; i < n; i++) {
        msis[i] = arr[i];
        for (let j = 0; j < i; j++) {
            if (arr[j] < arr[i] && msis[j] + arr[i] > msis[i]) {
                msis[i] = msis[j] + arr[i];
            }
        }
    }

    // Compute msds: maximum sum decreasing subsequence starting at each index
    // This is equivalent to maximum sum increasing subsequence when traversing from right to left
    for (let i = n - 1; i >= 0; i--) {
        msds[i] = arr[i];
        for (let j = n - 1; j > i; j--) {
            if (arr[j] < arr[i] && msds[j] + arr[i] > msds[i]) {
                msds[i] = msds[j] + arr[i];
            }
        }
    }

    // The maximum bitonic sum is the maximum of msis[i] + msds[i] - arr[i] for all i
    let maxSum = -Infinity;
    for (let i = 0; i < n; i++) {
        const bitonicSum = msis[i] + msds[i] - arr[i];
        if (bitonicSum > maxSum) {
            maxSum = bitonicSum;
        }
    }

    return maxSum;
}
```

