//Write a function to find the nth newman–shanks–williams prime number.
function newman_prime(n: number): number {
    // Newman-Shanks-Williams numbers are defined by the recurrence:
    // NSW(0) = 1, NSW(1) = 1, NSW(n) = 2*NSW(n-1) + NSW(n-2)
    // We need to find the nth NSW number that is also prime.

    if (n <= 0) {
        throw new Error("n must be a positive integer");
    }

    function isPrime(num: number): boolean {
        if (num < 2) return false;
        if (num === 2) return true;
        if (num % 2 === 0) return false;
        for (let i = 3; i <= Math.sqrt(num); i += 2) {
            if (num % i === 0) return false;
        }
        return true;
    }

    let count = 0;
    let a = 1; // NSW(0)
    let b = 1; // NSW(1)

    // Check NSW(0) = 1, which is not prime
    // Check NSW(1) = 1, which is not prime
    // Start from index 2

    let index = 1;
    while (true) {
        // Check if current b (NSW(index)) is prime
        if (isPrime(b)) {
            count++;
            if (count === n) {
                return b;
            }
        }

        // Compute next NSW number
        const next = 2 * b + a;
        a = b;
        b = next;
        index++;
    }
}
