```

```typescript
function max_sub_array_sum_repeated(a: number[], n: number, k: number): number {
    // Kadane's algorithm for a single array
    function kadane(arr: number[]): number {
        let maxSoFar = arr[0];
        let maxEndingHere = arr[0];
        for (let i = 1; i < arr.length; i++) {
            maxEndingHere = Math.max(arr[i], maxEndingHere + arr[i]);
            maxSoFar = Math.max(maxSoFar, maxEndingHere);
        }
        return maxSoFar;
    }

    // If k === 1, just return the max subarray sum of the original array
    if (k === 1) {
        return kadane(a);
    }

    // Compute the total sum of the array
    const totalSum = a.reduce((sum, val) => sum + val, 0);

    // The maximum subarray sum in the concatenated array (k copies) can be:
    // 1. The max subarray sum within a single copy (kadane(a))
    // 2. The max suffix sum of the array + max prefix sum of the array + (k-2) * totalSum (if k >= 2)
    //    This is because the optimal subarray might span across multiple copies.

    // Compute max prefix sum and max suffix sum for the array
    function maxPrefixSum(arr: number[]): number {
        let maxPrefix = arr[0];
        let currentPrefix = arr[0];
        for (let i = 1; i < arr.length; i++) {
            currentPrefix += arr[i];
            maxPrefix = Math.max(maxPrefix, currentPrefix);
        }
        return maxPrefix;
    }

    function maxSuffixSum(arr: number[]): number {
        let maxSuffix = arr[arr.length - 1];
        let currentSuffix = arr[arr.length - 1];
        for (let i = arr.length - 2; i >= 0; i--) {
            currentSuffix += arr[i];
            maxSuffix = Math.max(maxSuffix, currentSuffix);
        }
        return maxSuffix;
    }

    const maxSingle = kadane(a);
    const maxPref = maxPrefixSum(a);
    const maxSuff = maxSuffixSum(a);

    if (k === 2) {
        // For k=2, the max is either within one copy or spans the boundary
        return Math.max(maxSingle, maxPref + maxSuff);
    }

    // For k >= 3, the max could be:
    // - Within one copy: maxSingle
    // - Spanning across copies: maxSuff + maxPref + (k - 2) * totalSum
    // But we also need to consider if totalSum is negative, then we don't want to add it
    const maxCrossing = maxSuff + maxPref + (k - 2) * totalSum;

    return Math.max(maxSingle, maxCrossing);
}
