function find_kth(arr1: number[], arr2: number[], k: number): number {
    // Ensure arr1 is the smaller array for optimization
    if (arr1.length > arr2.length) {
        return find_kth(arr2, arr1, k);
    }

    let left = 0;
    let right = arr1.length;

    while (left <= right) {
        // Partition arr1 at index i and arr2 at index j such that i + j = k
        const i = Math.floor((left + right) / 2);
        const j = k - i;

        // Handle edge cases where partition is at the boundary
        const arr1LeftMax = i === 0 ? -Infinity : arr1[i - 1];
        const arr1RightMin = i === arr1.length ? Infinity : arr1[i];
        const arr2LeftMax = j === 0 ? -Infinity : arr2[j - 1];
        const arr2RightMin = j === arr2.length ? Infinity : arr2[j];

        if (arr1LeftMax <= arr2RightMin && arr2LeftMax <= arr1RightMin) {
            // Correct partition found
            return Math.max(arr1LeftMax, arr2LeftMax);
        } else if (arr1LeftMax > arr2RightMin) {
            // Move partition in arr1 to the left
            right = i - 1;
        } else {
            // Move partition in arr1 to the right
            left = i + 1;
        }
    }

    throw new Error("k is out of bounds");
}
