function get_ludic(n: number): number[] {
    if (n < 1) return [];

    // Create an array of numbers from 1 to n
    const numbers: number[] = [];
    for (let i = 1; i <= n; i++) {
        numbers.push(i);
    }

    // Remove elements that are at positions divisible by the current element
    // The first element is always 1, which is a ludic number
    // Then we remove every nth element where n is the current element

    let index = 0;
    while (index < numbers.length) {
        const current = numbers[index];
        // Remove every 'current'-th element starting from index + current
        // We need to remove elements at positions: index + current, index + 2*current, etc.
        // But we need to be careful with indices as we remove elements

        // Collect indices to remove
        const toRemove: number[] = [];
        for (let i = index + current; i < numbers.length; i += current) {
            toRemove.push(i);
        }

        // Remove in reverse order to maintain correct indices
        for (let i = toRemove.length - 1; i >= 0; i--) {
            numbers.splice(toRemove[i], 1);
        }

        index++;
    }

    return numbers;
}
