//Write a function to calculate whether the matrix is a magic square.
function magic_square_test(my_matrix: number[][]): boolean {
    const n = my_matrix.length;
    if (n === 0) return false;

    // Check if all rows have the same length
    for (let i = 0; i < n; i++) {
        if (my_matrix[i].length !== n) {
            return false;
        }
    }

    // Calculate the magic constant (sum of the first row)
    const magicSum = my_matrix[0].reduce((sum, val) => sum + val, 0);

    // Check all row sums
    for (let i = 0; i < n; i++) {
        const rowSum = my_matrix[i].reduce((sum, val) => sum + val, 0);
        if (rowSum !== magicSum) {
            return false;
        }
    }

    // Check all column sums
    for (let j = 0; j < n; j++) {
        let colSum = 0;
        for (let i = 0; i < n; i++) {
            colSum += my_matrix[i][j];
        }
        if (colSum !== magicSum) {
            return false;
        }
    }

    // Check main diagonal sum
    let mainDiagSum = 0;
    for (let i = 0; i < n; i++) {
        mainDiagSum += my_matrix[i][i];
    }
    if (mainDiagSum !== magicSum) {
        return false;
    }

    // Check anti-diagonal sum
    let antiDiagSum = 0;
    for (let i = 0; i < n; i++) {
        antiDiagSum += my_matrix[i][n - 1 - i];
    }
    if (antiDiagSum !== magicSum) {
        return false;
    }

    return true;
}
