function triples_sum_to_zero(l: number[]): boolean {
    const n = l.length;
    if (n < 3) {
        return false;
    }
    for (let i = 0; i < n - 2; i++) {
        for (let j = i + 1; j < n - 1; j++) {
            for (let k = j + 1; k < n; k++) {
                if (l[i] + l[j] + l[k] === 0) {
                    return true;
                }
            }
        }
    }
    return false;
}
