function count_samepair(list1: number[], list2: number[], list3: number[]): number {
    let count = 0;
    const minLength = Math.min(list1.length, list2.length, list3.length);
    for (let i = 0; i < minLength; i++) {
        if (list1[i] === list2[i] && list2[i] === list3[i]) {
            count++;
        }
    }
    return count;
}
