//Write a tsthon function to check whether all the bits are unset in the given range or not.
function all_Bits_Set_In_The_Given_Range(n: number, l: number, r: number): boolean {
    // Create a mask with all bits set from position l to r (1-indexed)
    // For 1-indexed positions, bit at position i corresponds to 2^(i-1)
    let mask = 0;
    for (let i = l; i <= r; i++) {
        mask |= (1 << (i - 1));
    }

    // Check if all bits in the range are unset (i.e., n & mask === 0)
    return (n & mask) === 0;
}
